//! Transport-independent diagnostics. The HTTP adapter maps `Response` to HTTP.
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

static NEXT: AtomicU64 = AtomicU64::new(0);

/// Generated by the server, never copied from an untrusted request header.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RequestId(String);
impl RequestId {
    pub fn new() -> Self {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        Self(format!(
            "{now:x}-{:x}-{:x}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ))
    }
    pub fn as_str(&self) -> &str {
        &self.0
    }
}
impl Default for RequestId {
    fn default() -> Self {
        Self::new()
    }
}

/// Only explicitly public fields cross the HTTP boundary; probe errors are discarded.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Resources {
    pub memory_used_bytes: Option<u64>,
    pub memory_total_bytes: Option<u64>,
    pub disk_available_bytes: Option<u64>,
}
pub trait Probes {
    type Error;
    fn storage_ready(&self) -> Result<(), Self::Error>;
    fn resources(&self) -> Result<Resources, Self::Error>;
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ErrorCode {
    StorageUnavailable,
    InternalError,
}
impl ErrorCode {
    pub fn code(self) -> &'static str {
        match self {
            Self::StorageUnavailable => "storage_unavailable",
            Self::InternalError => "internal_error",
        }
    }
    pub fn message(self) -> &'static str {
        match self {
            Self::StorageUnavailable => "Storage is unavailable",
            Self::InternalError => "An unexpected error occurred",
        }
    }
    pub fn status(self) -> u16 {
        match self {
            Self::StorageUnavailable => 503,
            Self::InternalError => 500,
        }
    }
}
#[derive(Debug, PartialEq, Eq)]
pub struct Response {
    pub status: u16,
    pub request_id: RequestId,
    pub body: Body,
}
#[derive(Debug, PartialEq, Eq)]
pub enum Body {
    Health { resources: Option<Resources> },
    Error { code: ErrorCode },
}
impl Response {
    pub fn error(request_id: RequestId, code: ErrorCode) -> Self {
        Self {
            status: code.status(),
            request_id,
            body: Body::Error { code },
        }
    }
    /// JSON uses only generated IDs, fixed messages and numeric resource values.
    pub fn json(&self) -> String {
        match &self.body {
            Body::Error { code } => format!(
                "{{\"code\":\"{}\",\"message\":\"{}\",\"request_id\":\"{}\"}}",
                code.code(),
                code.message(),
                self.request_id.as_str()
            ),
            Body::Health { resources } => {
                fn number(n: Option<u64>) -> String {
                    n.map(|v| v.to_string()).unwrap_or_else(|| "null".into())
                }
                let resource_json = match resources {
                    Some(r) => format!("{{\"memory_used_bytes\":{},\"memory_total_bytes\":{},\"disk_available_bytes\":{}}}", number(r.memory_used_bytes), number(r.memory_total_bytes), number(r.disk_available_bytes)),
                    None => "null".into(),
                };
                format!(
                    "{{\"status\":\"ready\",\"resources\":{},\"request_id\":\"{}\"}}",
                    resource_json,
                    self.request_id.as_str()
                )
            }
        }
    }
}
/// Resource telemetry is best-effort; a failed storage check makes readiness fail.
pub fn health<P: Probes>(probes: &P, request_id: RequestId) -> Response {
    if probes.storage_ready().is_err() {
        return Response::error(request_id, ErrorCode::StorageUnavailable);
    }
    Response {
        status: 200,
        request_id,
        body: Body::Health {
            resources: probes.resources().ok(),
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    struct Fake {
        storage: bool,
        resources: bool,
    }
    impl Probes for Fake {
        type Error = &'static str;
        fn storage_ready(&self) -> Result<(), Self::Error> {
            if self.storage {
                Ok(())
            } else {
                Err("/private/catalog token=secret")
            }
        }
        fn resources(&self) -> Result<Resources, Self::Error> {
            if self.resources {
                Ok(Resources {
                    memory_used_bytes: Some(42),
                    memory_total_bytes: Some(100),
                    disk_available_bytes: None,
                })
            } else {
                Err("secret")
            }
        }
    }
    #[test]
    fn ready_exposes_resource_values() {
        let r = health(
            &Fake {
                storage: true,
                resources: true,
            },
            RequestId::new(),
        );
        assert_eq!(r.status, 200);
        assert!(r.json().contains("\"memory_used_bytes\":42"));
        assert!(r.json().contains("\"disk_available_bytes\":null"));
    }
    #[test]
    fn storage_failure_is_distinct_and_sanitized() {
        let r = health(
            &Fake {
                storage: false,
                resources: true,
            },
            RequestId::new(),
        );
        assert_eq!(r.status, 503);
        assert!(r.json().contains("storage_unavailable"));
        assert!(!r.json().contains("private"));
        assert!(!r.json().contains("secret"));
    }
    #[test]
    fn unexpected_error_contains_same_id_without_details() {
        let id = RequestId::new();
        let r = Response::error(id.clone(), ErrorCode::InternalError);
        assert_eq!(r.status, 500);
        assert!(r.json().contains(id.as_str()));
        assert!(r.json().contains("internal_error"));
        assert!(!r.json().contains("secret"));
    }
    #[test]
    fn unavailable_telemetry_does_not_mask_readiness() {
        let r = health(
            &Fake {
                storage: true,
                resources: false,
            },
            RequestId::new(),
        );
        assert_eq!(r.status, 200);
        assert!(r.json().contains("\"resources\":null"));
    }
    #[test]
    fn request_ids_are_distinct() {
        assert_ne!(RequestId::new(), RequestId::new());
    }
}
